const phaseRows=(rows,policy)=>(rows??[]).map(row=>row&&typeof row==='object'&&!Array.isArray(row)?Object.fromEntries(Object.entries(row).filter(([key])=>policy.showGradient||!/(gradient|derivative|adjoint|delta|moment|candidate)/i.test(key)).filter(([key])=>policy.showUpdate||!/(afterParameter|updatedWeight|candidateParameter)/i.test(key))):row);
