function scalarCards(items){return `<div class="ti-metrics">${items.map(([label,value,unit])=>`<div><span>${esc(label)}</span><strong>${esc(typeof value==='number'?number(value):value??'—')}</strong>${unit?`<small>${esc(unit)}</small>`:''}</div>`).join('')}</div>`;}
