 const labels={value:'数值',rawValue:'原值',normalized:'标准化值',weight:'权重',coefficient:'系数',contribution:'贡献',contributionEV:'贡献 / eV',sum:'求和',name:'名称',label:'计算项',paramIndex:'参数 ID',parameterIndex:'参数 ID',atomIndex:'原子索引',from:'来源 j',to:'目标 i',featureIndex:'特征索引',input:'输入',output:'输出',z:'加权和 z',activation:'激活 a',derivative:'输出导数',localDerivative:'局部导数',adjoint:'伴随量',operation:'运算',species:'元素',scale:'缩放',r:'距离 / Å'};
 return `<div class="ti-table-caption">${esc(caption)} · 第 ${start+1}–${start+shown.length} 项 / 共 ${rows.length} 项</div><div class="ti-table-scroll" tabindex="0" aria-label="${esc(caption)}，可横向滚动"><table><thead><tr>${keys.map(k=>`<th>${esc(labels[k]??k)}</th>`).join('')}</tr></thead><tbody>${objects.map(r=>{const patch={};for(const key of ['paramIndex','atomIndex','featureIndex','round','channel','neuronIndex','layerIndex'])if(Number.isInteger(r[key]))patch[key]=r[key];if(!Number.isInteger(patch.paramIndex)&&Number.isInteger(r.parameterIndices?.[0]))patch.paramIndex=r.parameterIndices[0];if(Number.isInteger(r.path))patch.pathIndex=r.path;if(Number.isInteger(r.from))patch.edgeFrom=r.from;if(Number.isInteger(r.to))patch.atomIndex=r.to;return `<tr>${keys.map((k,j)=>`<td>${j===0&&selectRows&&Object.keys(patch).length?selectable(patch,esc(pretty(r[k]))):esc(pretty(r[k]))}</td>`).join('')}</tr>`;}).join('')}</tbody></table></div>`;
