function pagination(page,total,size,kind){const pages=Math.max(1,Math.ceil(total/size));return pages>1?`<div class="ti-pagination">${action(kind+'-prev','← 上一页',page<=0?'disabled':'')}<span>${Math.min(page+1,pages)} / ${pages}</span>${action(kind+'-next','下一页 →',page>=pages-1?'disabled':'')}</div>`:'';}
